/**
 * The committed record of a locally run AI tournament: for each table size,
 * every pair of strategies and how often each came out ahead. Generated by
 * `pnpm --filter @boardgames/core tournament <slug>` into the game's web folder
 * and rendered read-only on the game's Tournament page.
 */

import { z } from "zod";

export const TOURNAMENT_RESULTS_FORMAT = 1;

const MatchupSchema = z
  .object({
    /** Strategy ids; `a` sat in the even seats of even-numbered games. */
    a: z.string().min(1),
    b: z.string().min(1),
    games: z.number().int().min(1),
    aWins: z.number().int().min(0),
    bWins: z.number().int().min(0),
    draws: z.number().int().min(0),
    /** Mean final score of the side's seats per game; `null` when the game keeps no score. */
    avgScoreA: z.number().nullable(),
    avgScoreB: z.number().nullable(),
  })
  .refine((m) => m.aWins + m.bWins + m.draws === m.games, {
    message: "aWins + bWins + draws must equal games",
  })
  .refine((m) => m.a !== m.b, { message: "a matchup needs two different strategies" });
export type TournamentMatchup = z.infer<typeof MatchupSchema>;

const TableSchema = z.object({
  playerCount: z.number().int().min(2),
  matchups: z.array(MatchupSchema),
});
export type TournamentTable = z.infer<typeof TableSchema>;

export const TournamentResultsSchema = z.object({
  formatVersion: z.literal(TOURNAMENT_RESULTS_FORMAT),
  slug: z.string().min(1),
  /** ISO timestamp of the latest run merged into this file. */
  generatedAt: z.string().min(1),
  /** Label snapshot at generation time, in the manifest's order. */
  strategies: z.array(z.object({ id: z.string().min(1), label: z.string().min(1) })).min(2),
  tables: z.array(TableSchema).min(1),
});
export type TournamentResults = z.infer<typeof TournamentResultsSchema>;

/** Outcome tallies for one matchup, before they are frozen into the file. */
export interface MatchupTally {
  games: number;
  aWins: number;
  bWins: number;
  draws: number;
  scoreA: number;
  scoreB: number;
  scored: number;
}

export function emptyTally(): MatchupTally {
  return { games: 0, aWins: 0, bWins: 0, draws: 0, scoreA: 0, scoreB: 0, scored: 0 };
}

export function tallyToMatchup(a: string, b: string, t: MatchupTally): TournamentMatchup {
  const round1 = (n: number) => Math.round(n * 10) / 10;
  return {
    a,
    b,
    games: t.games,
    aWins: t.aWins,
    bWins: t.bWins,
    draws: t.draws,
    avgScoreA: t.scored > 0 ? round1(t.scoreA / t.scored) : null,
    avgScoreB: t.scored > 0 ? round1(t.scoreB / t.scored) : null,
  };
}

/**
 * Fold a fresh run into an earlier file: matchups the run played replace the
 * old ones (in either orientation); everything else is kept, so a heavy game
 * can be run one table size or one strategy at a time.
 */
export function mergeResults(
  previous: TournamentResults | null,
  fresh: TournamentResults,
): TournamentResults {
  if (!previous) return fresh;
  const key = (n: number, a: string, b: string) => `${n}:${[a, b].sort().join("|")}`;
  const played = new Set(
    fresh.tables.flatMap((t) => t.matchups.map((m) => key(t.playerCount, m.a, m.b))),
  );
  const sizes = new Set([...previous.tables, ...fresh.tables].map((t) => t.playerCount));
  const tables = [...sizes]
    .sort((x, y) => x - y)
    .map((playerCount) => {
      const kept = (
        previous.tables.find((t) => t.playerCount === playerCount)?.matchups ?? []
      ).filter((m) => !played.has(key(playerCount, m.a, m.b)));
      const added = fresh.tables.find((t) => t.playerCount === playerCount)?.matchups ?? [];
      return { playerCount, matchups: [...kept, ...added] };
    });
  return { ...fresh, tables };
}

/** Win rate of `row` against `col` at one table, and the average score gap; `null` if unplayed. */
export function headToHead(
  table: TournamentTable,
  row: string,
  col: string,
): { winRate: number; scoreDiff: number | null; games: number } | null {
  for (const m of table.matchups) {
    const forward = m.a === row && m.b === col;
    if (!forward && !(m.a === col && m.b === row)) continue;
    const wins = (forward ? m.aWins : m.bWins) + m.draws / 2;
    const mine = forward ? m.avgScoreA : m.avgScoreB;
    const theirs = forward ? m.avgScoreB : m.avgScoreA;
    return {
      winRate: wins / m.games,
      scoreDiff: mine === null || theirs === null ? null : Math.round((mine - theirs) * 10) / 10,
      games: m.games,
    };
  }
  return null;
}
